WITH not_flagged AS (SELECT s.* FROM products s WHERE NOT EXISTS (SELECT 1 FROM store_sales ch WHERE ch.product_id = s.id AND ch.sale_date <= s.launch_date)) SELECT s.id, s.product_name, s.price, s.launch_date, s.tags, s.supplier_id, (SELECT MAX(t2.stock_qty) FROM products t2 WHERE t2.supplier_id = s.supplier_id) AS max_product_stock_qty FROM not_flagged s ORDER BY supplier_id NULLS FIRST;
